  ContentUnavailableError,
  InvalidContentResponseError,
} from "@common-practice/content/errors";
import { checkedPageOperation } from "@common-practice/content/response-check";
import { Content, contentClientTimeout } from "@common-practice/content/service";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Match from "effect/Match";
import type * as HttpClientError from "effect/http/HttpClientError";
import * as HttpApiClient from "effect/http-api/HttpApiClient";
import { ContentApi } from "./api";
import { HttpApiAddress } from "./config";

const httpFailure = (
  operation: "get-page" | "list-pages",
  error: HttpClientError.HttpClientError,
) =>
  Match.value(error.reason).pipe(
    Match.tag("DecodeError", () => new InvalidContentResponseError({ operation })),
    Match.tag("EmptyBodyError", () => new InvalidContentResponseError({ operation })),
    Match.orElse(() => new ContentUnavailableError({ operation })),
  );

export const contentHttpClientLayer = Layer.effect(
  Content,
  Effect.gen(function* () {
    const options = yield* HttpApiAddress;
    const client = yield* HttpApiClient.make(ContentApi, options);
    return Content.of({
      listPages: client.pages.listPages({}).pipe(
        Effect.timeoutOrElse({
          duration: contentClientTimeout,
          orElse: () => Effect.fail(new ContentUnavailableError({ operation: "list-pages" })),
        }),
        Effect.catchTags({
          HttpClientError: (error) => Effect.fail(httpFailure("list-pages", error)),
          SchemaError: () =>
            Effect.fail(new InvalidContentResponseError({ operation: "list-pages" })),
        }),
        Effect.withSpan("Content.listPages"),
      ),
      getPage: checkedPageOperation({
        getPage: (request) =>
          client.pages
            .getPage({
              params: { id: request.id },
              query: { format: request.format },
            })
            .pipe(
              Effect.timeoutOrElse({
                duration: contentClientTimeout,
                orElse: () => Effect.fail(new ContentUnavailableError({ operation: "get-page" })),
              }),
              Effect.catchTags({
                HttpClientError: (error) => Effect.fail(httpFailure("get-page", error)),
                SchemaError: () =>
                  Effect.fail(new InvalidContentResponseError({ operation: "get-page" })),
              }),
            ),
      }),
    });
  }),
);
import { HttpApiAddress } from "@common-practice/http/config";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Predicate from "effect/Predicate";
import * as Schema from "effect/Schema";
import { fromCloudflareFetcher, toHttpClient } from "alchemy/Cloudflare/Bridge";
import { contentHttpClientLayer } from "@common-practice/http/client";
import { trainingHttpClientLayer } from "@common-practice/http/training-client";
import { ApiOrigin } from "@common-practice/http/schemas";
import { WebsiteApi } from "./service";
import { WebsiteAppConfig } from "../config";
import { reifyBoundConfigProvider } from "alchemy/Runtime";
import * as HttpClient from "effect/http/HttpClient";
import type * as HttpServerRequest from "effect/http/HttpServerRequest";
import * as HttpServerError from "effect/http/HttpServerError";
import { ApiBindingError } from "./errors";
import * as ConfigProvider from "effect/ConfigProvider";

// Keep the host object's identity. Alchemy owns the conversion into Effect.
export const ApiBinding = Schema.declare<Parameters<typeof fromCloudflareFetcher>[0]>(
  (value): value is Parameters<typeof fromCloudflareFetcher>[0] =>
    Predicate.hasProperty(value, "fetch") &&
    Predicate.isFunction(value.fetch) &&
    Predicate.hasProperty(value, "connect") &&
    Predicate.isFunction(value.connect),
);
export const forwardApiRequest = ({
  request,
  binding,
}: {
  readonly request: HttpServerRequest.HttpServerRequest;
  readonly binding: typeof ApiBinding.Type;
}) =>
  fromCloudflareFetcher(binding)
    .fetch(request)
    .pipe(
      // Alchemy reports rejected host Promises as defects. Keep the Website's
      // named transport failure without turning interruption into a response.
      Effect.catchDefect(() => Effect.fail(new ApiBindingError({ operation: "forward" }))),
      Effect.mapError(() => new ApiBindingError({ operation: "forward" })),
    );

export const readWebsiteConfiguration = Effect.fn("WebsiteApi.configuration")(
  function* ({
    apiUrl,
    websiteUrl,
    capture,
    stage: rawStage,
  }: {
    readonly apiUrl: unknown;
    readonly websiteUrl: unknown;
    readonly capture: unknown;
    readonly stage: unknown;
  }) {
    const bindings = {
      COMMON_PRACTICE_API_URL: apiUrl,
      COMMON_PRACTICE_WEBSITE_URL: websiteUrl,
      COMMON_PRACTICE_POSTHOG_CONFIG: capture,
      COMMON_PRACTICE_STAGE: rawStage,
    };
    // Use the same native Alchemy unwrapping as its Effect Worker host. Only
    // these named settings enter the provider; each Config owns its Schema check.
    const source = ConfigProvider.fromUnknown(bindings);
    const provider = reifyBoundConfigProvider(source, bindings);
    return yield* WebsiteAppConfig.parse(provider);
  },
  Effect.mapError(() => new ApiBindingError({ operation: "binding" })),
);

// A private binding is an Effect HttpClient transport, rather than a second Content implementation.
export const ApiClientsLive = Layer.unwrap(
  Effect.gen(function* () {
    const api = yield* WebsiteApi;
    const transport = toHttpClient({
      fetch: (request) =>
        api.forward(request).pipe(
          Effect.mapError(
            (cause) =>
              new HttpServerError.HttpServerError({
                reason: new HttpServerError.InternalError({ request, cause }),
              }),
          ),
        ),
    });
    const options = { baseUrl: ApiOrigin.make("https://backend") };
    return Layer.mergeAll(
      contentHttpClientLayer.pipe(Layer.provide(Layer.succeed(HttpApiAddress, options))),
      trainingHttpClientLayer.pipe(Layer.provide(Layer.succeed(HttpApiAddress, options))),
    ).pipe(Layer.provide(Layer.succeed(HttpClient.HttpClient, transport)));
  }),
);

